<script setup>
import { ref, onMounted } from 'vue'
import { api } from '../api'
const props = defineProps({ courseId: String })
const emit = defineEmits(['changed'])
const items = ref([]), form = ref(null), editing = ref(null), error = ref(''), busy = ref(false)
const criterion = () => ({ title: '', description: '', weight: 1, levels: ['', '', '', ''] })
async function load() { try { items.value = await api(`/courses/${props.courseId}/rubrics`) } catch (e) { error.value = e.message } }
onMounted(load)
function start(item) { editing.value = item; form.value = item ? { title: item.title, criteria: item.criteria.map(c => ({ ...c, levels: [...c.levels] })), expectedVersion: item.versionNo } : { title: '', criteria: [criterion()], expectedVersion: 0 } }
async function save() { busy.value = true; error.value = ''; try { await api(`/courses/${props.courseId}/rubrics${editing.value ? `/${editing.value.id}` : ''}`, { method: editing.value ? 'PUT' : 'POST', body: form.value }); form.value = null; await load(); emit('changed') } catch (e) { error.value = e.message } finally { busy.value = false } }
</script>
<template><section class="surface form-surface"><div class="section-title"><h2>課程評分規準</h2><button class="button secondary" @click="start(null)">建立規準</button></div><p class="muted">已關聯作業的規準修改時會建立新版本，保留原評分依據。每項四級，依權重換算作業滿分。</p><p v-if="error" role="alert" class="error-box">{{ error }}</p><p v-if="!items.length" class="empty-inline">尚未建立評分規準。</p><div v-for="item in items" :key="item.id" class="section-title"><span>{{ item.title }} · v{{ item.versionNo }} · {{ item.criteria.length }} 項</span><button class="text-button" @click="start(item)">編輯規準</button></div><form v-if="form" @submit.prevent="save"><fieldset :disabled="busy"><label>規準名稱<input v-model="form.title" required maxlength="200" /></label><div v-for="(c, i) in form.criteria" :key="i" class="question-editor"><label>規準項目 {{ i + 1 }}<input v-model="c.title" required maxlength="200" /></label><label>項目說明<textarea v-model="c.description" maxlength="4000"></textarea></label><label>權重<input v-model.number="c.weight" type="number" min="0.001" max="1000" step="0.001" required /></label><label v-for="(_, n) in c.levels" :key="n">{{ n + 1 }} 級描述<input v-model="c.levels[n]" required maxlength="4000" /></label><button type="button" class="text-button" :disabled="form.criteria.length === 1" @click="form.criteria.splice(i, 1)">移除項目</button></div><button type="button" class="button secondary" :disabled="form.criteria.length >= 20" @click="form.criteria.push(criterion())">新增規準項目</button><div class="form-bottom"><button type="button" class="button secondary" @click="form = null">取消</button><button class="button primary" type="submit">儲存規準</button></div></fieldset></form></section></template>
